import {MAP} from '../map.js';
import {SUN_MAGNET} from '../data.js';
import {P} from './palette.js';
import {Particles} from './particles.js';
import {kick,seed,clamp} from './animation.js';
import {effectFamily} from './effects.js';

// Presentation owns these snapshots. It never writes to simulation entities or RNG.
export class VisualState{
 constructor(game){this.game=game;this.time=0;this.entities=new Map();this.ghosts=[];this.shots=new Map();this.effects=new WeakSet();this.particles=new Particles();this.links=[];this.shake=0;this.magnetField=0;this.previousPlants=game.plants;this.previousRuntime=game.runTime;this.subscriptions=[];this.bind()}
 bind(){const on=(name,fn)=>this.subscriptions.push(this.game.events.on(name,fn)),T=MAP.tileSize;on('plant:placed',e=>{this.particles.burst((e.x+.5)*T,(e.y+.5)*T+12,'dirt',8);this.particles.burst((e.x+.5)*T,(e.y+.5)*T,'leaf',4)});on('evolution:selected',({evolution})=>{for(const p of this.game.plants)if(p.id===evolution.plant)this.particles.burst((p.x+.5)*T,(p.y+.5)*T,'spark',10,P.evolution)});on('sun:magnetized',({drop})=>this.particles.burst(drop.x*T,drop.y*T,'spark',3,P.sun));on('sun:collected',({drop})=>this.particles.burst(drop.x*T,drop.y*T,'spark',6,P.sun));on('enemy:heal',({enemy,targets})=>{this.particles.burst(enemy.x*T,enemy.y*T,'leaf',8,P.heal);for(const target of targets)this.particles.burst(target.x*T,target.y*T,'leaf',3,P.heal)});on('enemy:special',({enemy,type,target})=>{if(type==='sunStealCancelled'){const at=target||enemy;this.particles.burst(at.x*T,at.y*T,'spark',5,P.cream)}});on('enemy:volatileExplosion',({enemy})=>{this.shake=Math.max(this.shake,2);this.particles.burst(enemy.x*T,enemy.y*T,'smoke',10,P.green);this.particles.burst(enemy.x*T,enemy.y*T,'ember',7,P.fire)});on('enemy:elite',({enemy})=>this.particles.burst(enemy.x*T,enemy.y*T,'spark',5,P.evolution));on('sector:unlocked',({sector})=>{for(let i=0;i<12;i++){const x=sector.tiles.x1+seed(i+1)*(sector.tiles.x2-sector.tiles.x1+1),y=sector.tiles.y1+seed(i+9)*(sector.tiles.y2-sector.tiles.y1+1);this.particles.burst(x*T,y*T,'leaf',3)}});on('boss:defeated',()=>{this.shake=3});on('wave:end',()=>{for(const p of this.game.plants){const v=this.entities.get(p.uid);if(v&&p.hp>v.hp)this.particles.burst((p.x+.5)*T,(p.y+.5)*T,'leaf',3,P.heal)}})}
 dispose(){for(const off of this.subscriptions)off();this.subscriptions=[]}
 reset(){this.entities.clear();this.ghosts=[];this.shots.clear();this.links=[];this.effects=new WeakSet();this.particles.items=[];this.time=0;this.shake=0;this.magnetField=0}
 update(dt){const g=this.game,T=MAP.tileSize;if(g.runTime<this.previousRuntime||(g.plants!==this.previousPlants&&g.wave===0&&g.runTime===0))this.reset();this.previousPlants=g.plants;this.previousRuntime=g.runTime;const paused=g.paused||globalThis.document?.hidden,level=Math.max(0,Math.min(SUN_MAGNET.levels.length-1,g.meta.gardenTools?.magnet||0)),fieldActive=!paused&&g.pointer.active&&SUN_MAGNET.levels[level].radius>0,fieldTarget=fieldActive?(g.sunDrops.some(s=>s.magnetized) ? .18+.025*level : .025):0,delta=paused?0:Math.min(.1,Math.max(0,dt));this.magnetField+=(fieldTarget-this.magnetField)*Math.min(1,delta*8);this.time+=delta;this.particles.step(delta);this.shake=Math.max(0,this.shake-delta*10);const alive=new Set();
  for(const kind of ['plant','zombie'])for(const e of kind==='plant'?g.plants:g.zombies){alive.add(e.uid);let v=this.entities.get(e.uid);const x=(e.x+(kind==='plant'?.5:0))*T,y=(e.y+(kind==='plant'?.5:0))*T;if(!v){v={uid:e.uid,kind,born:this.time,hp:e.hp,attacks:e.attacks||0,cool:e.cool||0,production:e.productionTimer||0,x,y,hitAt:-99,attackAt:-99,produceAt:-99};this.entities.set(e.uid,v)}
   if(e.hp<v.hp){v.hitAt=this.time;this.particles.burst(x,y,kind==='plant'?'leaf':'dirt',4,kind==='plant'?P.light:P.skinShade);if(e.lastDamageTaken>200)this.shake=Math.max(this.shake,1.8)}v.healing=e.hp>v.hp;if(e.hp>v.hp+1)this.particles.burst(x,y,'leaf',2,P.heal);
   if((e.attacks||0)>v.attacks||kind==='zombie'&&(e.cool||0)>v.cool+.15){v.attackAt=this.time;if(e.id==='bonkChoy')this.particles.burst(x,y-5,'spark',3,P.cream);if(e.id==='repeater'&&g.selectedEvolutions[e.id]==='gatlingBurst'&&e.attacks%4===0)this.particles.burst(x+14,y-10,'leaf',7)}
   if(kind==='plant'&&(e.productionTimer||0)+.1<v.production){v.produceAt=this.time;this.particles.burst(x,y-14,g.selectedEvolutions[e.id]==='healingBloom'?'leaf':'spark',7,g.selectedEvolutions[e.id]==='healingBloom'?P.heal:P.sun)}
   v.moving=Math.hypot(v.x-x,v.y-y)>.02;v.x=x;v.y=y;v.hp=e.hp;v.attacks=e.attacks||0;v.cool=e.cool||0;v.production=e.productionTimer||0;v.snapshot={...e};v.evolution=g.selectedEvolutions[e.id];v.ascension=g.selectedAscensions?.[e.id];v.level=g.levels[e.id]||1;if(kind==='plant'&&e.id==='potatoMine')v.arming=clamp(e.age/Math.max(.1,g.stats(e).armTime));
   if(e.bossId==='crusher'&&(e.chargeState==='charging'||e.chargeState==='telegraph')&&Math.floor(this.time*12)!==v.dustTick){v.dustTick=Math.floor(this.time*12);this.particles.burst(x,y+22,'dirt',e.chargeState==='charging'?3:1)}
  }
  for(const [id,v] of this.entities)if(!alive.has(id)){this.ghosts.push({...v,died:this.time,duration:v.snapshot.bossId?1.1:.65});if(this.ghosts.length>60)this.ghosts.shift();this.particles.burst(v.x,v.y,v.kind==='plant'?'leaf':'smoke',v.snapshot.bossId?18:6);this.entities.delete(id)}
  this.ghosts=this.ghosts.filter(v=>this.time-v.died<v.duration);const current=new Set(g.shots);for(const s of g.shots){let record=this.shots.get(s);if(!record){const owner=g.plants.find(p=>Math.abs(p.x+.5-s.startX)<.1&&Math.abs(p.y+.5-s.startY)<.1);record={x:s.x,y:s.y,source:s,evolution:owner?g.selectedEvolutions[owner.id]:''};this.shots.set(s,record);if(owner&&s.target){const visual=this.entities.get(owner.uid);if(visual)visual.facing=s.target.x<s.startX?-1:1}}record.x=s.x;record.y=s.y}
  for(const [s,v] of this.shots)if(!current.has(s)){if(g.state==='playing'&&s.target&&Math.hypot(s.target.x-v.x,s.target.y-v.y)<.65){const x=s.target.x*T,y=s.target.y*T;this.particles.burst(x,y,s.splash?'leaf':s.critical?'spark':'leaf',s.splash?9:3,s.critical?P.sun:null);if(s.siege)this.shake=Math.max(this.shake,2.2);if(s.split||s.pierce||s.fragment){let count=0;const cap=s.fragment?3:s.split||s.pierce;for(const target of g.zombies)if(target!==s.target&&Math.hypot(target.x-s.target.x,target.y-s.target.y)<3&&count++<cap)this.links.push({x,y,tx:target.x*T,ty:target.y*T,born:this.time,type:s.pierce?'pierce':s.fragment?'fragment':'split'})}}this.shots.delete(s)}this.links=this.links.filter(l=>this.time-l.born<.3);
  for(const e of g.effects)if(!this.effects.has(e)){this.effects.add(e);const family=effectFamily(e);if(['explosion','boss','bossDeath','siege'].includes(family)){this.shake=Math.max(this.shake,family==='bossDeath'?3:2);this.particles.burst(e.x*T,e.y*T,'dirt',14,null,1.4);this.particles.burst(e.x*T,e.y*T,'smoke',8);this.particles.burst(e.x*T,e.y*T,'ember',5)}if(family==='heavy'||family==='critical')this.particles.burst(e.x*T,e.y*T,'spark',5,P.critical)}
 }
 options(v){if(!v)return{};return{uid:v.uid,spawn:this.time-v.born,hit:kick(this.time,v.hitAt,.35)*2,attack:kick(this.time,v.attackAt,.4)*2,production:kick(this.time,v.produceAt,.7)*2,attacks:v.attacks,moving:v.moving,ratio:clamp(v.hp/Math.max(1,v.snapshot.maxHp)),level:v.level,evolution:v.evolution,ascension:v.ascension,focus:v.snapshot.focusStacks||0,armed:(v.arming??1)>=1,arming:v.arming??1,facing:v.facing||1,healing:v.healing}}
}
